#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import json
import shutil
from pathlib import Path

PAYLOADS = {'hara_exceptions_java': '', 'hara_context_exception_block': '', 'hara_result_normalize_block': '', 'hara_result_error_fn': '', 'hara_exception_test_java': '', 'hara_exception_corpus_test_java': '', 'rust_exception_section': '', 'rust_native_error_fn': '', 'rust_result_error_fn': '', 'rust_normalize_error_fn': '', 'rust_file_error_fn': '', 'rust_host_error_fn': '', 'rust_runtime_exception_tests': ' ', 'transport_error_block': '', 'transport_frame_block': '', 'transport_test_fact': '', 'provenance_error_block': '', 'provenance_test_hal': ''}


def payload(name: str) -> str:
    return base64.b64decode(PAYLOADS[name]).decode()


def read(path: Path) -> str:
    return path.read_text()


def write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content)


def replace_once(source: str, old: str, new: str, label: str) -> str:
    amount = source.count(old)
    if amount != 1:
        raise SystemExit(f"{label}: expected exactly one replacement seam, found {amount}")
    return source.replace(old, new, 1)


def replace_region(source: str, start: str, end: str, replacement: str, label: str) -> str:
    start_index = source.find(start)
    if start_index < 0:
        raise SystemExit(f"{label}: start seam not found")
    end_index = source.find(end, start_index + len(start))
    if end_index < 0:
        raise SystemExit(f"{label}: end seam not found")
    return source[:start_index] + replacement + source[end_index:]


def transform_runtime(root: Path) -> None:
    write(
        root / "core/java/src/main/java/hara/truffle/HaraExceptions.java",
        payload("hara_exceptions_java"),
    )
    write(
        root / "core/java/src/test/java/hara/truffle/HaraExceptionContractTest.java",
        payload("hara_exception_test_java"),
    )
    write(
        root / "core/java/src/test/java/hara/truffle/HaraExceptionCorpusTest.java",
        payload("hara_exception_corpus_test_java"),
    )

    path = root / "core/java/src/main/java/hara/truffle/HaraContext.java"
    source = read(path)
    source = replace_once(
        source,
        '          Map.entry("Error", java.util.List.of("new", "message", "class")),',
        '          Map.entry("Error", java.util.List.of("new", "message", "class", "native-type")),',
        str(path),
    )
    old_export = (
        '          Map.of(\n'
        '              "new", "ex-info",\n'
        '              "message", "ex-message",\n'
        '              "class", "ex-class"));'
    )
    new_export = (
        '          Map.of(\n'
        '              "new", "ex-info",\n'
        '              "message", "ex-message",\n'
        '              "class", "ex-class",\n'
        '              "native-type", "ex-native-type"));'
    )
    source = replace_once(source, old_export, new_export, str(path))
    source = replace_region(
        source,
        '    target.define(\n        "ex",',
        '    target.define("load-string"',
        payload("hara_context_exception_block"),
        str(path),
    )
    write(path, source)

    path = root / "core/java/src/main/java/hara/truffle/HaraResult.java"
    source = read(path)
    source = replace_once(
        source,
        '  private static final Keyword ERROR_CODE_KEY = Keyword.create("code");',
        '  private static final Keyword ERROR_CODE_KEY = Keyword.create("ex", "code");',
        str(path),
    )
    source = replace_region(
        source,
        "  private static Ex.Info resultError(",
        '  @SuppressWarnings({"rawtypes", "unchecked"})\n  private static IMapType',
        payload("hara_result_error_fn") + "\n",
        str(path),
    )
    source = replace_region(
        source,
        "  private static Ex.Info normalizeError(Object value) {",
        "  private static String errorMessage",
        payload("hara_result_normalize_block") + "\n",
        str(path),
    )
    write(path, source)

    path = root / "core/rust/src/core/value.rs"
    source = replace_region(
        read(path),
        "pub(crate) fn exception_function_values()",
        "\npub(crate) fn basic_function_values()",
        payload("rust_exception_section") + "\n",
        str(path),
    )
    write(path, source)

    path = root / "core/rust/src/core/primitive.rs"
    source = replace_region(
        read(path),
        "fn native_error_values(",
        "\nfn comparison(",
        payload("rust_native_error_fn") + "\n",
        str(path),
    )
    write(path, source)

    path = root / "core/rust/src/core/inventory.rs"
    source = replace_once(
        read(path),
        '("Error", &["new", "message", "class"]),',
        '("Error", &["new", "message", "class", "native-type"]),',
        str(path),
    )
    write(path, source)

    path = root / "core/rust/src/core/native_result.rs"
    source = read(path)
    source = replace_once(
        source,
        '        let code_key = Value::Keyword(Keyword::from("code"));',
        '        let code_key = Value::Keyword(Keyword::from("ex/code"));',
        str(path),
    )
    source = replace_region(
        source,
        "fn result_error(",
        "\nfn context_with(",
        payload("rust_result_error_fn") + "\n",
        str(path),
    )
    source = replace_region(
        source,
        "fn normalize_error(value: Value)",
        "\nfn error_equal(",
        payload("rust_normalize_error_fn") + "\n",
        str(path),
    )
    write(path, source)

    path = root / "core/rust/src/file.rs"
    source = replace_region(
        read(path),
        "pub fn file_error_value(",
        "\nfn resolved(",
        payload("rust_file_error_fn") + "\n",
        str(path),
    )
    write(path, source)

    path = root / "core/rust/src/core/native.rs"
    source = replace_region(
        read(path),
        "fn host_error(",
        "\nfn native_test_events(",
        payload("rust_host_error_fn") + "\n",
        str(path),
    )
    write(path, source)

    path = root / "core/rust/src/runtime/tests.rs"
    source = read(path)
    marker = (
        "    #[test]\n"
        "    fn issue_133_cases_run_from_the_shared_core_language_conformance_corpus()"
    )
    if "fn portable_exception_classes_and_native_diagnostics_are_distinct()" in source:
        raise SystemExit(f"{path}: exception test tranche already present")
    source = replace_once(
        source,
        marker,
        payload("rust_runtime_exception_tests") + "\n" + marker,
        str(path),
    )
    write(path, source)

    replacement_roots = [
        root / "core/rust/src",
        root / "core/rust/raw/src",
        root / "core/java/src/test",
    ]
    for base in replacement_roots:
        if not base.exists():
            continue
        for candidate in base.rglob("*"):
            if candidate.suffix not in {".rs", ".java"}:
                continue
            source = read(candidate)
            updated = source.replace("error/code", "ex/code")
            if updated != source:
                write(candidate, updated)


def transform_hal(relative: Path, source: str) -> str:
    rel = relative.as_posix()
    if rel == "core/lib/src/db/node/transport.hal":
        source = replace_region(
            source,
            "(defn error->wire",
            "(defn frame->wire",
            payload("transport_error_block") + "\n",
            rel,
        )
        source = replace_region(
            source,
            "(defn frame->wire",
            "(defn wire->frame",
            payload("transport_frame_block") + "\n",
            rel,
        )
    elif rel == "core/lib/test/db/node/transport_test.hal":
        marker = "(def results\n  ["
        source = replace_once(
            source,
            marker,
            marker + payload("transport_test_fact"),
            rel,
        )
    elif rel == "core/lib/src/lang/common/provenance.hal":
        source = replace_region(
            source,
            "(defn error-with-provenance",
            "(defn throw-with-provenance",
            payload("provenance_error_block") + "\n",
            rel,
        )

    source = source.replace(":error/code", ":ex/code")
    source = source.replace('"error/code"', '"ex/code"')
    return source


def build_candidates(root: Path, output: Path) -> list[str]:
    if output.exists():
        shutil.rmtree(output)
    output.mkdir(parents=True)
    roots = [
        root / "core/lib/src",
        root / "core/lib/src-lang",
        root / "core/lib/test",
        root / "core/lib/test-lang",
        root / "core/lib/integration",
    ]
    changed: list[str] = []
    special = {
        "core/lib/src/db/node/transport.hal",
        "core/lib/test/db/node/transport_test.hal",
        "core/lib/src/lang/common/provenance.hal",
    }
    for base in roots:
        if not base.exists():
            continue
        for path in sorted(base.rglob("*.hal")):
            relative = path.relative_to(root)
            source = read(path)
            if (
                relative.as_posix() not in special
                and ":error/code" not in source
                and '"error/code"' not in source
            ):
                continue
            updated = transform_hal(relative, source)
            if updated != source:
                target = output / relative
                write(target, updated)
                changed.append(relative.as_posix())

    provenance_test = Path("core/lib/test/lang/common/provenance_test.hal")
    write(output / provenance_test, payload("provenance_test_hal"))
    if provenance_test.as_posix() not in changed:
        changed.append(provenance_test.as_posix())

    changed.sort()
    write(output / "manifest.json", json.dumps(changed, indent=2) + "\n")
    return changed


def install_candidates(root: Path, output: Path) -> list[str]:
    paths = json.loads(read(output / "manifest.json"))
    for relative in paths:
        source = output / relative
        if not source.is_file():
            raise SystemExit(f"missing candidate {source}")
        write(root / relative, read(source))
    return paths

DELIMITERS = set("()[]{}\"';`,~@^ \t\r\n,")


def skip_ws_comment(source: str, index: int) -> int:
    size = len(source)
    while index < size:
        if source[index].isspace() or source[index] == ",":
            index += 1
            continue
        if source[index] == ";":
            newline = source.find("\n", index)
            return size if newline < 0 else skip_ws_comment(source, newline + 1)
        break
    return index


def parse_token(source: str, index: int) -> tuple[int, str | None, list[tuple[str | None, list]]]:
    index = skip_ws_comment(source, index)
    if index >= len(source):
        return index, None, []
    char = source[index]
    if char == '"':
        cursor = index + 1
        while cursor < len(source):
            if source[cursor] == "\\":
                cursor += 2
            elif source[cursor] == '"':
                return cursor + 1, None, []
            else:
                cursor += 1
        raise ValueError("unterminated string")
    if char == "\\":
        cursor = index + 1
        while cursor < len(source) and source[cursor] not in DELIMITERS:
            cursor += 1
        return cursor, None, []
    if char in "'`@^":
        end, _, nested = parse_token(source, index + 1)
        return end, None, nested
    if char == "~":
        offset = 2 if index + 1 < len(source) and source[index + 1] == "@" else 1
        end, _, nested = parse_token(source, index + offset)
        return end, None, nested
    if char == "#":
        if index + 1 < len(source) and source[index + 1] in "({":
            return parse_container(source, index + 1)
        cursor = index + 1
        while cursor < len(source) and source[cursor] not in DELIMITERS:
            cursor += 1
        if cursor < len(source) and source[cursor] in "([{":
            end, _, nested = parse_token(source, cursor)
            return end, None, nested
        return cursor, source[index:cursor], []
    if char in "([{":
        return parse_container(source, index)
    cursor = index
    while cursor < len(source) and source[cursor] not in DELIMITERS:
        cursor += 1
    return cursor, source[index:cursor], []


def parse_container(source: str, index: int) -> tuple[int, str | None, list[tuple[str | None, list]]]:
    opening = source[index]
    closing = {"(": ")", "[": "]", "{": "}"}[opening]
    cursor = index + 1
    children: list[tuple[str | None, list]] = []
    while True:
        cursor = skip_ws_comment(source, cursor)
        if cursor >= len(source):
            raise ValueError(f"unterminated {opening}")
        if source[cursor] == closing:
            return cursor + 1, None, children
        end, atom, nested = parse_token(source, cursor)
        children.append((atom, nested))
        cursor = end


def audit_ex_arities(source: str, path: str) -> list[str]:
    violations: list[str] = []
    cursor = 0
    stack: list[list[tuple[str | None, list]]] = []
    while cursor < len(source):
        cursor = skip_ws_comment(source, cursor)
        if cursor >= len(source):
            break
        end, atom, nested = parse_token(source, cursor)
        stack.append(nested)
        while stack:
            children = stack.pop()
            if children:
                head = children[0][0]
                if head in {"ex", "std.foundation/ex"} and len(children) != 3:
                    violations.append(f"{path}: ex form has {len(children) - 1} arguments")
                stack.extend(child_nested for _, child_nested in children if child_nested)
        cursor = end
    return violations

def audit(root: Path) -> None:
    active_roots = [
        root / "core/lib/src",
        root / "core/lib/src-lang",
        root / "core/rust/src",
        root / "core/rust/raw/src",
        root / "core/java/src/main",
    ]
    offenders: list[str] = []
    for base in active_roots:
        if not base.exists():
            continue
        for path in base.rglob("*"):
            if path.suffix not in {".hal", ".rs", ".java"}:
                continue
            source = read(path)
            if "error/code" in source:
                offenders.append(str(path.relative_to(root)))
    if offenders:
        raise SystemExit("active :error/code contract remains: " + ", ".join(offenders))

    arity_violations: list[str] = []
    class_catches: list[str] = []
    for base in [root / "core/lib/src", root / "core/lib/src-lang"]:
        if not base.exists():
            continue
        for path in base.rglob("*.hal"):
            source = read(path)
            arity_violations.extend(audit_ex_arities(source, str(path.relative_to(root))))
            if "catch :ex.class/" in source:
                class_catches.append(str(path.relative_to(root)))
    if arity_violations:
        raise SystemExit("non-canonical ex arity: " + "; ".join(arity_violations))
    if class_catches:
        raise SystemExit("class-based catch behavior remains: " + ", ".join(class_catches))


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("operation", choices=["runtime", "candidates", "install", "audit"])
    parser.add_argument("--root", default=".")
    parser.add_argument("--output", default="/tmp/exception-candidates")
    args = parser.parse_args()
    root = Path(args.root).resolve()
    output = Path(args.output).resolve()

    if args.operation == "runtime":
        transform_runtime(root)
    elif args.operation == "candidates":
        paths = build_candidates(root, output)
        print(json.dumps({"candidates": paths}, indent=2))
    elif args.operation == "install":
        paths = install_candidates(root, output)
        print(json.dumps({"installed": paths}, indent=2))
    elif args.operation == "audit":
        audit(root)


if __name__ == "__main__":
    main()
